<?php
declare(strict_types=1);
namespace Fasiliti;
function managers():array{return ['admin','manager'];}
function manage(array $u):bool{return in_array($u['role'],managers(),true);}
function definitions():array{return [
 'suppliers'=>['table'=>'suppliers','label'=>'Pembekal','fields'=>['code'=>['Kod','text'],'name'=>['Nama pembekal','text'],'email'=>['E-mel','optional'],'phone'=>['Telefon','optional'],'active'=>['Aktif','boolean']]],
 'assets'=>['table'=>'assets','label'=>'Aset','fields'=>['code'=>['No. aset','text'],'name'=>['Nama aset','text'],'room_id'=>['Ruang','room'],'category'=>['Kategori','text'],'serial'=>['No. siri','optional'],'condition_status'=>['Keadaan','choice',['Baik','Perlu servis','Rosak']],'purchase_cost'=>['Nilai perolehan (RM)','money'],'warranty_end'=>['Tamat waranti','date?'],'supplier_id'=>['Pembekal','supplier?'],'active'=>['Aktif','boolean']]],
 'contracts'=>['table'=>'contracts','label'=>'Kontrak','fields'=>['code'=>['Kod kontrak','text'],'title'=>['Tajuk','text'],'supplier_id'=>['Pembekal','supplier'],'starts'=>['Tarikh mula','date'],'ends'=>['Tarikh tamat','date'],'amount'=>['Nilai kontrak (RM)','money'],'active'=>['Aktif','boolean']]],
 'parts'=>['table'=>'parts','label'=>'Alat ganti','fields'=>['code'=>['Kod stok','text'],'name'=>['Nama item','text'],'unit'=>['Unit','text'],'reorder_level'=>['Paras pesanan semula','number'],'unit_cost'=>['Kos seunit (RM)','money'],'active'=>['Aktif','boolean']]],
 'policies'=>['table'=>'sla_policies','pk'=>'priority','label'=>'Dasar SLA','fields'=>['priority'=>['Keutamaan','choice',['Tinggi','Sederhana','Rendah']],'response_hours'=>['Respons (jam)','integer'],'resolve_hours'=>['Selesai (jam)','integer']]],
 'budgets'=>['table'=>'budgets','label'=>'Bajet','fields'=>['period'=>['Bulan (YYYY-MM)','period'],'amount'=>['Peruntukan (RM)','money'],'note'=>['Catatan','optional']]],
 'meters'=>['table'=>'meters','label'=>'Meter utiliti','fields'=>['code'=>['Kod meter','text'],'name'=>['Nama','text'],'room_id'=>['Ruang','room'],'unit'=>['Unit bacaan','choice',['kWh','m³','L']],'active'=>['Aktif','boolean']]]
];}
function dateValue(array $d,string $key,bool $optional=false):?string{$v=text($d,$key,10,!$optional);if($optional&&$v==='')return null;$date=\DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$date||$date->format('Y-m-d')!==$v)fail(422,'Tarikh '.$key.' tidak sah.');return $v;}
function utcValue(array $d,string $key):string{$v=text($d,$key,30);$t=\DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$v,new \DateTimeZone('UTC'));if(!$t||$t->format('Y-m-d\TH:i')!==$v)fail(422,'Masa '.$key.' mesti YYYY-MM-DDTHH:MM dalam UTC.');return $t->format('Y-m-d H:i:s');}
function amount(array $d,string $key):float{$v=number($d,$key,0,999999999);if(abs(round($v,2)-$v)>0.0000001)fail(422,'Wang hanya menerima dua tempat perpuluhan.');return round($v,2);}
function period(array $d,string $key='period'):string{$v=text($d,$key,7);if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/D',$v))fail(422,'Bulan mesti YYYY-MM.');return $v;}
function ref(string $kind,mixed $id):array {
 $tables=['room'=>'rooms','asset'=>'assets','supplier'=>'suppliers','user'=>'users','contract'=>'contracts','part'=>'parts','meter'=>'meters'];if(!isset($tables[$kind]))fail(422,'Rujukan tidak sah.');
 if(!is_string($id)&&!is_int($id))fail(422,'ID rujukan tidak sah.');$r=query('SELECT * FROM '.$tables[$kind].' WHERE id=?',[$id])->fetch();if(!$r||($kind==='room'?$r['archived_at']!==null:isset($r['active'])&&!$r['active']))fail(422,'Rujukan '.$kind.' tidak aktif / tidak ditemui.');return $r;
}
function version(array $row,array $d):void{if(integer($d,'version',1)!==(int)$row['version'])fail(409,'Rekod telah berubah. Muat semula sebelum menyunting.');}
function opAudit(string $action,string $entity,string|int $id,mixed $before,mixed $after):void{audit($action,$entity,(string)$id,$before,$after);}
function notifyUser(int $id,string $message,string $entity,string|int $key):void{query('INSERT INTO notifications(user_id,message,entity_type,entity_id) VALUES(?,?,?,?)',[$id,$message,$entity,(string)$key]);}
function notifyManagers(string $message,string $entity,string|int $id):void{foreach(query("SELECT id FROM users WHERE active=1 AND role IN ('admin','manager')")->fetchAll() as $u)notifyUser((int)$u['id'],$message,$entity,$id);}
function genericSave(string $resource,array $d,?string $id):array {
 $defs=definitions();$def=$defs[$resource];$table=$def['table'];$pk=$def['pk']??'id';return transaction(function()use($d,$id,$resource,$def,$table,$pk){
 $old=null;if($id!==null){$old=query("SELECT * FROM $table WHERE $pk=? FOR UPDATE",[$id])->fetch();if(!$old)fail(404,'Rekod tidak ditemui.');version($old,$d);}
 $values=[];foreach($def['fields'] as $k=>[$label,$type]){
  $options=$def['fields'][$k][2]??[];$base=rtrim($type,'?');$optional=str_ends_with($type,'?');
  if($base==='boolean')$v=(int)boolean($d,$k);elseif($base==='number')$v=number($d,$k,0,1000000);elseif($base==='money')$v=amount($d,$k);elseif($base==='integer')$v=integer($d,$k,1,87600);elseif($base==='date')$v=dateValue($d,$k,$optional);elseif($base==='period')$v=period($d,$k);elseif($base==='choice')$v=choice($d,$k,$options);elseif(in_array($base,['room','asset','supplier','user','contract'])){$v=$d[$k]??null;if($optional&&($v===''||$v===null))$v=null;else ref($base,$v);}else $v=text($d,$k,match($k){'code'=>64,'email'=>190,'phone'=>40,'serial'=>100,'category'=>64,'unit'=>32,'note'=>500,default=>150},$type!=='optional');$values[$k]=$v;
 }
 if($resource==='assets'&&$old&&$old['room_id']!==$values['room_id'])fail(422,'Gunakan tindakan Pindah aset supaya sejarah lokasi direkodkan.');
 if($resource==='assets'&&!$values['active']&&query("SELECT id FROM work_orders WHERE asset_id=? AND status NOT IN ('Selesai','Dibatalkan') LIMIT 1",[$id])->fetch())fail(422,'Aset masih mempunyai kerja terbuka.');
 if($resource==='assets'&&!$values['active']&&query('SELECT id FROM maintenance_plans WHERE asset_id=? AND active=1 LIMIT 1',[$id])->fetch())fail(422,'Nyahaktif pelan berkala sebelum mengarkib aset.');
 if($resource==='contracts'&&$values['ends']<$values['starts'])fail(422,'Tamat kontrak mendahului tarikh mula.');
 if($resource==='suppliers'&&$values['email']!==''&&!filter_var($values['email'],FILTER_VALIDATE_EMAIL))fail(422,'E-mel pembekal tidak sah.');
 if($resource==='policies'&&$values['resolve_hours']<$values['response_hours'])fail(422,'SLA selesai tidak boleh mendahului SLA respons.');
 if($resource==='policies'&&$old&&$values['priority']!==$id)fail(422,'Kod keutamaan tidak boleh diubah.');
 if($id===null){$cols=array_keys($values);query("INSERT INTO $table (".implode(',',$cols).') VALUES('.implode(',',array_fill(0,count($cols),'?')).')',array_values($values));$id=$pk==='id'?(string)db()->lastInsertId():$values[$pk];}else{query("UPDATE $table SET ".implode(',',array_map(fn($k)=>"$k=?",array_keys($values))).",version=version+1 WHERE $pk=?",[...array_values($values),$id]);}
 $saved=query("SELECT * FROM $table WHERE $pk=?",[$id])->fetch();opAudit($old?'update':'create',$resource,$id,$old,$saved);return $saved;
 });
}
function workAccess(array $u,array $w,bool $write=true):void{if(manage($u))return;if($u['role']==='technician'&&(int)$w['assigned_to']===$u['id'])return;if(!$write&&$u['role']==='auditor')return;fail(403,'Anda tidak dibenarkan mengakses kerja ini.');}
function requestAccess(array $u,array $r):void{if(manage($u)||$u['role']==='auditor'||(int)$r['created_by']===$u['id'])return;fail(403,'Aduan ini bukan dalam akses anda.');}
function entityAccess(array $u,string $kind,string $id,bool $write=false):void {
 if($kind==='request'){$r=query('SELECT * FROM service_requests WHERE id=?',[$id])->fetch();if(!$r)fail(404,'Aduan tidak ditemui.');requestAccess($u,$r);if($write&&$u['role']==='auditor')fail(403,'Akaun audit adalah baca sahaja.');return;}
 if($kind==='work'){$w=query('SELECT * FROM work_orders WHERE id=?',[$id])->fetch();if(!$w)fail(404,'Kerja tidak ditemui.');workAccess($u,$w,$write);return;}
 if(!in_array($kind,['room','asset'],true))fail(422,'Jenis lampiran tidak sah.');ref($kind,$id);if($write&&!manage($u))fail(403,'Lampiran memerlukan pengurus ruang.');
}
function operationsData(array $u):array {
 $manager=manage($u);$audit=$u['role']==='auditor';$all=$manager||$audit;
 $requests=query('SELECT r.*,rm.name AS room_name FROM service_requests r JOIN rooms rm ON rm.id=r.room_id'.($all?'':' WHERE r.created_by=?').' ORDER BY r.id DESC',$all?[]:[$u['id']])->fetchAll();
 $works=query("SELECT w.*,u.name AS technician,rm.name AS room_name,COALESCE((SELECT SUM(labor_cost) FROM work_logs l WHERE l.work_order_id=w.id),0) AS labor_cost,COALESCE((SELECT SUM(total_cost) FROM stock_movements s WHERE s.work_order_id=w.id AND quantity<0),0) AS material_cost,(w.due_at<UTC_TIMESTAMP() AND w.status NOT IN ('Selesai','Dibatalkan')) AS overdue FROM work_orders w JOIN users u ON u.id=w.assigned_to JOIN rooms rm ON rm.id=w.room_id".($all?'':' WHERE w.assigned_to=?').' ORDER BY w.id DESC',$all?[]:[$u['id']])->fetchAll();$ids=array_column($works,'id');
 $logs=$ids?query('SELECT * FROM work_logs WHERE work_order_id IN ('.implode(',',array_fill(0,count($ids),'?')).') ORDER BY id DESC',$ids)->fetchAll():[];
 $movements=($all||$u['role']==='technician')?query('SELECT * FROM stock_movements ORDER BY id DESC LIMIT 1000')->fetchAll():[];
 $result=['definitions'=>definitions(),'requests'=>$requests,'work'=>$works,'logs'=>$logs,'movements'=>$movements,'plans'=>($all?query('SELECT * FROM maintenance_plans ORDER BY id DESC')->fetchAll():[]),'bookings'=>query('SELECT b.*,r.name AS room_name,u.name AS requested_by FROM bookings b JOIN rooms r ON r.id=b.room_id JOIN users u ON u.id=b.user_id'.($all?'':' WHERE b.user_id=?').' ORDER BY b.starts DESC',$all?[]:[$u['id']])->fetchAll(),'people'=>($manager?query("SELECT id,name,role FROM users WHERE active=1 AND role IN ('admin','manager','technician') ORDER BY name")->fetchAll():[]),'notifications'=>query('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 100',[$u['id']])->fetchAll(),'charges'=>$all?query('SELECT c.*,r.name AS room_name FROM room_charges c JOIN rooms r ON r.id=c.room_id ORDER BY id DESC LIMIT 1000')->fetchAll():[],'readings'=>query('SELECT *,value-LAG(value) OVER(PARTITION BY meter_id ORDER BY recorded_at) AS consumption FROM meter_readings ORDER BY recorded_at DESC LIMIT 1000')->fetchAll(),'asset_moves'=>query('SELECT * FROM asset_moves ORDER BY id DESC LIMIT 500')->fetchAll(),'attachments'=>[]];
 foreach(definitions() as $key=>$def)$result[$key]=query('SELECT * FROM '.$def['table'].' ORDER BY '.($def['pk']??'id').' DESC')->fetchAll();
 if(!$all){$result['contracts']=[];$result['budgets']=[];$result['suppliers']=[];}
 foreach(query('SELECT id,entity_type,entity_id,original_name,mime,size_bytes,created_at FROM attachments ORDER BY created_at DESC LIMIT 1000')->fetchAll() as $a){try{entityAccess($u,$a['entity_type'],$a['entity_id']);$result['attachments'][]=$a;}catch(HttpError){}}
 return $result;
}
function scheduleMaintenance(?string $today=null):array {
 $today??=gmdate('Y-m-d');$count=0;$plans=query('SELECT id FROM maintenance_plans WHERE active=1 AND next_due<=? ORDER BY id',[$today])->fetchAll();foreach($plans as $plan){$count+=transaction(function()use($plan,$today){$p=query('SELECT * FROM maintenance_plans WHERE id=? FOR UPDATE',[$plan['id']])->fetch();if(!$p['active'])return 0;$generated=0;$a=ref('asset',$p['asset_id']);$tech=ref('user',$p['assigned_to']);if(!in_array($tech['role'],['admin','manager','technician'],true))fail(422,'Pelan mempunyai juruteknik tidak sah.');ref('room',$a['room_id']);
 while($p['next_due']<=$today&&$generated<30){$due=$p['next_due'];if(!query('SELECT id FROM maintenance_occurrences WHERE plan_id=? AND due_date=?',[$p['id'],$due])->fetch()){query('INSERT INTO work_orders(asset_id,room_id,title,assigned_to,due_at,checklist) VALUES(?,?,?,?,?,?)',[$p['asset_id'],$a['room_id'],$p['name'],$p['assigned_to'],$due.' 23:59:59',$p['checklist']]);$wo=(int)db()->lastInsertId();query('INSERT INTO maintenance_occurrences(plan_id,due_date,work_order_id) VALUES(?,?,?)',[$p['id'],$due,$wo]);opAudit('scheduled','work',$wo,null,['plan_id'=>$p['id'],'due'=>$due]);notifyUser((int)$p['assigned_to'],'Kerja berkala: '.$p['name'],'work',$wo);$generated++;}$p['next_due']=gmdate('Y-m-d',strtotime($due.' +'.$p['interval_days'].' days UTC'));}
 query('UPDATE maintenance_plans SET next_due=?,version=version+1 WHERE id=?',[$p['next_due'],$p['id']]);return $generated;});}return ['generated'=>$count];
}
function operationRoutes(string $path,string $method,array $u):void {
 if(!str_starts_with($path,'/api/v1/ops'))return;
 $route=substr($path,strlen('/api/v1/ops'));
 if($method==='GET'&&$route==='')json(operationsData($u));
 if(preg_match('~^/(suppliers|assets|contracts|parts|policies|budgets|meters)(?:/([A-Za-z0-9_-]+))?$~',$route,$m)&&in_array($method,['POST','PUT'],true)){allow(managers());$id=$m[2]??null;if(($method==='PUT')!==($id!==null))fail(405,'Method tidak sepadan dengan endpoint.');json(['record'=>genericSave($m[1],body(),$id)],$id===null?201:200);}
 if($method==='POST'&&preg_match('~^/assets/(\d+)/move$~',$route,$m)){
 allow(managers());$d=body();transaction(function()use($m,$d,$u){$a=query('SELECT * FROM assets WHERE id=? FOR UPDATE',[$m[1]])->fetch();if(!$a)fail(404,'Aset tidak ditemui.');version($a,$d);$r=ref('room',$d['room_id']??null);$reason=text($d,'reason',500);if($a['room_id']===$r['id'])fail(422,'Lokasi baharu sama.');if(query("SELECT id FROM work_orders WHERE asset_id=? AND status NOT IN ('Selesai','Dibatalkan') LIMIT 1",[$a['id']])->fetch())fail(422,'Selesaikan kerja terbuka sebelum memindahkan aset.');query('INSERT INTO asset_moves(asset_id,old_room,new_room,actor_id,reason) VALUES(?,?,?,?,?)',[$a['id'],$a['room_id'],$r['id'],$u['id'],$reason]);query('UPDATE assets SET room_id=?,version=version+1 WHERE id=?',[$r['id'],$a['id']]);opAudit('move','asset',$a['id'],$a,['room_id'=>$r['id'],'reason'=>$reason]);});json(['ok'=>true]);}
 if($method==='POST'&&$route==='/requests'){
 allow(['admin','manager','reporter','viewer','technician']);$d=body();$result=transaction(function()use($d,$u){$room=ref('room',$d['room_id']??null);$asset=$d['asset_id']??null;if($asset!==null&&$asset!==''){ $a=ref('asset',$asset);if($a['room_id']!==$room['id'])fail(422,'Lokasi aset tidak sepadan dengan aduan.');}else $asset=null;$priority=choice($d,'priority',['Tinggi','Sederhana','Rendah']);$policy=query('SELECT * FROM sla_policies WHERE priority=?',[$priority])->fetch();$response=gmdate('Y-m-d H:i:s',time()+3600*(int)$policy['response_hours']);$resolve=gmdate('Y-m-d H:i:s',time()+3600*(int)$policy['resolve_hours']);query('INSERT INTO service_requests(room_id,asset_id,created_by,subject,description,priority,response_due,resolve_due) VALUES(?,?,?,?,?,?,?,?)',[$room['id'],$asset,$u['id'],text($d,'subject',150),text($d,'description',5000),$priority,$response,$resolve]);$id=(int)db()->lastInsertId();opAudit('create','request',$id,null,$d);notifyManagers('Aduan baharu: '.text($d,'subject',150),'request',$id);return ['id'=>$id];});json($result,201);}
 if($method==='POST'&&preg_match('~^/requests/(\d+)/review$~',$route,$m)){
 allow(managers());$d=body();$result=transaction(function()use($d,$m,$u){$r=query('SELECT * FROM service_requests WHERE id=? FOR UPDATE',[$m[1]])->fetch();if(!$r)fail(404,'Aduan tidak ditemui.');version($r,$d);if($r['status']!=='Baharu')fail(422,'Aduan telah disemak.');$action=choice($d,'action',['accept','reject']);$reason=text($d,'reason',500);$status=$action==='accept'?'Diterima':'Ditolak';query('UPDATE service_requests SET status=?,reason=?,accepted_at=UTC_TIMESTAMP(),version=version+1 WHERE id=?',[$status,$reason,$r['id']]);opAudit('review','request',$r['id'],$r,['status'=>$status,'reason'=>$reason]);notifyUser((int)$r['created_by'],'Aduan #'.$r['id'].': '.$status,'request',$r['id']);return ['ok'=>true];});json($result);}
 if($method==='POST'&&$route==='/work'){
 allow(managers());$d=body();$result=transaction(function()use($d){$r=null;$rid=$d['request_id']??null;if($rid!==null&&$rid!==''){$r=query('SELECT * FROM service_requests WHERE id=? FOR UPDATE',[$rid])->fetch();if(!$r||!in_array($r['status'],['Diterima','Dalam tindakan'],true))fail(422,'Aduan belum diterima atau sudah ditutup.');}$room=ref('room',$r?$r['room_id']:($d['room_id']??null));$asset=$r?$r['asset_id']:($d['asset_id']??null);if($asset){$a=ref('asset',$asset);if($a['room_id']!==$room['id'])fail(422,'Lokasi aset tidak sepadan.');}else$asset=null;$tech=ref('user',$d['assigned_to']??null);if(!in_array($tech['role'],['admin','manager','technician']))fail(422,'Pilih juruteknik yang sah.');$contract=$d['contract_id']??null;if($contract){$c=ref('contract',$contract);if($c['starts']>gmdate('Y-m-d')||$c['ends']<gmdate('Y-m-d'))fail(422,'Kontrak di luar tempoh.');}else$contract=null;$due=$r?$r['resolve_due']:utcValue($d,'due_at');query('INSERT INTO work_orders(request_id,asset_id,room_id,title,assigned_to,contract_id,due_at,checklist) VALUES(?,?,?,?,?,?,?,?)',[$r?$r['id']:null,$asset,$room['id'],text($d,'title',150),$tech['id'],$contract,$due,'[]']);$id=(int)db()->lastInsertId();if($r)query("UPDATE service_requests SET status='Dalam tindakan',version=version+1 WHERE id=?",[$r['id']]);opAudit('assign','work',$id,null,$d);notifyUser((int)$tech['id'],'Arahan kerja baharu #'.$id,'work',$id);return ['id'=>$id];});json($result,201);}
 if($method==='POST'&&preg_match('~^/work/(\d+)/status$~',$route,$m)){
 $d=body();transaction(function()use($d,$m,$u){$hint=query('SELECT request_id FROM work_orders WHERE id=?',[$m[1]])->fetch();if(!$hint)fail(404,'Kerja tidak ditemui.');if($hint['request_id'])query('SELECT id FROM service_requests WHERE id=? FOR UPDATE',[$hint['request_id']]);$w=query('SELECT * FROM work_orders WHERE id=? FOR UPDATE',[$m[1]])->fetch();workAccess($u,$w);version($w,$d);$action=choice($d,'action',['start','submit','verify','return','cancel']);$status=match($action){'start'=>'Dalam pelaksanaan','submit'=>'Menunggu pengesahan','verify'=>'Selesai','return'=>'Dalam pelaksanaan','cancel'=>'Dibatalkan'};
 $allowed=['start'=>['Ditugaskan'],'submit'=>['Dalam pelaksanaan'],'verify'=>['Menunggu pengesahan'],'return'=>['Menunggu pengesahan'],'cancel'=>['Ditugaskan','Dalam pelaksanaan','Menunggu pengesahan']];if(!in_array($w['status'],$allowed[$action]))fail(422,'Peralihan status tidak dibenarkan.');if(in_array($action,['verify','return','cancel'])&&!manage($u))fail(403,'Pengesahan / pembatalan memerlukan pengurus.');$reason=in_array($action,['return','cancel'])?text($d,'reason',500):text($d,'reason',500,false);$results=$w['check_results'];if($action==='submit'){$checks=json_decode($w['checklist'],true);$provided=$d['checks']??[];if(!is_array($provided)||!array_is_list($provided)||count($provided)!==count($checks)||count(array_filter($provided,fn($v)=>$v===true))!==count($checks))fail(422,'Semua senarai semak mesti lengkap.');if(!query('SELECT id FROM work_logs WHERE work_order_id=? LIMIT 1',[$w['id']])->fetch())fail(422,'Rekod pelaksanaan kerja diperlukan.');$results=json_encode($provided);}
 query('UPDATE work_orders SET status=?,check_results=?,closed_at=?,version=version+1 WHERE id=?',[$status,$results,in_array($status,['Selesai','Dibatalkan'])?gmdate('Y-m-d H:i:s'):null,$w['id']]);if($w['request_id']){$open=(int)query("SELECT COUNT(*) FROM work_orders WHERE request_id=? AND status NOT IN ('Selesai','Dibatalkan')",[$w['request_id']])->fetchColumn();$done=(int)query("SELECT COUNT(*) FROM work_orders WHERE request_id=? AND status='Selesai'",[$w['request_id']])->fetchColumn();$requestStatus=$open===0&&$done>0?'Ditutup':($open===0?'Diterima':'Dalam tindakan');query('UPDATE service_requests SET status=?,closed_at=?,version=version+1 WHERE id=?',[$requestStatus,$requestStatus==='Ditutup'?gmdate('Y-m-d H:i:s'):null,$w['request_id']]);$r=query('SELECT created_by FROM service_requests WHERE id=?',[$w['request_id']])->fetch();notifyUser((int)$r['created_by'],'Status aduan #'.$w['request_id'].': '.$requestStatus,'request',$w['request_id']);}opAudit($action,'work',$w['id'],$w,['status'=>$status,'reason'=>$reason]);if($action==='submit')notifyManagers('Kerja #'.$w['id'].' menunggu pengesahan.','work',$w['id']);});json(['ok'=>true]);}
 if($method==='POST'&&preg_match('~^/work/(\d+)/logs$~',$route,$m)){
